def find_all_matches(grid, pattern):
    matches = []
    h, w = len(grid), len(grid[0])
    ph, pw = len(pattern), len(pattern[0])

    for r in range(h - ph + 1):
        for c in range(w - pw + 1):
            match = True
            for dr in range(ph):
                for dc in range(pw):
