# Now scan output for similar non-7 patterns
def extract_non_bg_patterns(grid, bg_val=7):
    """Find all connected components of non-bg values"""
    h, w = len(grid), len(grid[0])
    visited = set()
    patterns = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg_val and (r,c) not in visited:
                # BFS to get connected component
                comp = []
                queue = [(r,c)]
                visited.add((r,c))

                while queue:
                    cr, cc = queue.pop(0)
                    comp.append((cr, cc, grid[cr][cc]))

                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if grid[nr][nc] != bg_val and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))
                patterns.append(comp)
    return patterns

